package com.csust.eyediagnosis.workflow.evidence;
import org.junit.jupiter.api.Test; import java.util.List; import java.util.concurrent.atomic.AtomicInteger; import static org.junit.jupiter.api.Assertions.*;
class EvidenceRetrievalGraphTest { @Test void usesOneRetrievalWhenFirstResultIsSufficient() { AtomicInteger calls = new AtomicInteger(); EvidenceRetrievalGraphResult result = graph(query -> { calls.incrementAndGet(); return List.of(EvidenceFixtures.candidate()); }).execute(EvidenceFixtures.valid(), EvidenceFixtures.exposure(EvidenceFixtures.valid())); assertTrue(result.batch().sufficiency().sufficient()); assertEquals(1, result.retrievalCalls()); assertEquals(0, result.rewriteCalls()); assertEquals(1, calls.get()); }
    @Test void permitsExactlyOneRewriteThenAccepts() { AtomicInteger calls = new AtomicInteger(); EvidenceCandidate invalid = new EvidenceCandidate("s", "r", "c", "t", "q", "bad", java.util.Set.of("amd"), java.util.Set.of("DISEASE_OVERVIEW"), KnowledgeVisibility.CURATED_PUBLIC, KnowledgeReviewStatus.APPROVED, false, .1, java.util.Map.of()); EvidenceRetrievalGraphResult result = graph(query -> calls.incrementAndGet() == 1 ? List.of(invalid) : List.of(EvidenceFixtures.candidate())).execute(EvidenceFixtures.valid(), EvidenceFixtures.exposure(EvidenceFixtures.valid())); assertTrue(result.batch().sufficiency().sufficient()); assertEquals(2, result.retrievalCalls()); assertEquals(1, result.rewriteCalls()); }
    @Test void exhaustsAfterSecondRetrievalAndSkipsAllSafetyAbstentions() { AtomicInteger calls = new AtomicInteger(); EvidenceRetrievalGovernanceGraph graph = graph(query -> { calls.incrementAndGet(); return List.of(); }); EvidenceRetrievalGraphResult exhausted = graph.execute(EvidenceFixtures.valid(), EvidenceFixtures.exposure(EvidenceFixtures.valid())); assertEquals(EvidenceSufficiencyReasonCode.REWRITE_EXHAUSTED, exhausted.batch().sufficiency().reasonCode()); assertEquals(2, exhausted.retrievalCalls()); EvidenceRetrievalGraphResult skipped = graph.execute(EvidenceFixtures.abstention(com.csust.eyediagnosis.workflow.domain.SafetyAbstentionReasonCode.LOW_CONFIDENCE), EvidenceFixtures.exposure(EvidenceFixtures.abstention(com.csust.eyediagnosis.workflow.domain.SafetyAbstentionReasonCode.LOW_CONFIDENCE))); assertEquals(0, skipped.retrievalCalls()); assertEquals(0, skipped.rewriteCalls()); assertEquals(2, calls.get()); }
    private static EvidenceRetrievalGovernanceGraph graph(EvidenceRetriever retriever) { FixedEvidenceTermCatalog catalog = new FixedEvidenceTermCatalog(); return new EvidenceRetrievalGovernanceGraph(new EvidenceRetrievalAction(retriever, catalog), new RetrievalSourceValidationAction(new DefaultRetrievalSourceValidator(catalog)), new QueryRewriteAction(new CatalogEvidenceQueryRewriter(catalog))); } }
